/bin/bash -c "python - <<'PY'
import cv2, numpy as np
im=cv2.imread('first_frame.png')
poly=np.array([[65,42],[157,46],[154,127],[60,121]],np.int32)
for exp in [2,4,6]:
 mask=np.zeros(im.shape[:2],np.uint8); cv2.fillPoly(mask,[poly],255)
 if exp: mask=cv2.dilate(mask,np.ones((2*exp+1,2*exp+1),np.uint8))
 for rad in [3,7,15]:
  for algo,name in [(cv2.INPAINT_TELEA,'telea'),(cv2.INPAINT_NS,'ns')]:
   out=cv2.inpaint(im,mask,rad,algo)
   cv2.imwrite(f'.tmp/inpaint_e{exp}_r{rad}_{name}.png',out)
PY"

